`,_jsxs(_components.span,{className:`line`,children:[_jsx(_components.span,{style:{color:`#116329`,"--shiki-dark":`#9CDCFE`},children:` "remedy_hint"`}),_jsx(_components.span,{style:{color:`#1F2328`,"--shiki-dark":`#D4D4D4`},children:`: `}),_jsx(_components.span,{style:{color:`#0A3069`,"--shiki-dark":`#CE9178`},children:`"Retry after your in-flight requests settle (see the Retry-After header). Adding credits at https://openrouter.ai/settings/credits raises your in-flight budget, up to a capped ceiling."`})]}),`
