t&n=izaS1l2UMuz6sm1H&q=85&s=2a3997622bc9ef8e44f7182e900f8a40 2500w`}),`
`,_jsx(_components.p,{children:_jsx(_components.strong,{children:`Fly.io runs your apps close to your users. This page explains how our free trial works and what you can use before you add a payment method.`})}),`
`,_jsx(Heading,{level:`2`,id:`free-trial-overview`,children:`Free Trial overview`}),`
`,_jsxs(_components.p,{children:[`New accounts get `,_jsx(_components.strong,{children:`$1 of free credit`}),`, with no credit card required. You can spend it on Machines, Sprites and Managed Postgres. The credit lasts for 7 days or until you use it up, whichever comes first.`]}),`
`,_jsx(_components.p,{children:`That’s enough to deploy a real app or try a few Sprites before you decide if Fly.io is a fit for you.`}),`
`,_jsx(_components.p,{children:`The credit applies to your personal organization, the one we create for you at signup.`}),`
`,_jsx(Heading,{level:`2`,id:`trial-limits`,children:`Trial limits`}),`
`,_jsx(_components.p,{children:`Until you add a credit card, the trial has these limits:`}),`
`,_jsxs(_components.ul,{children:[`
`,_jsxs(_components.li,{children:[_jsx(_components.strong,{children:`Machines:`}),` up to 10 at a time across your organization. Stopped Machines count toward the limit, so destroy any you don’t need.`]}),`
`,_jsxs(_components.li,{children:[_jsx(_components.strong,{children:`Machine size:`}),` up to `,_jsx(_components.code,{children:`shared-cpu-2x`}),`, with up to 4GB of memory`]}),`
`,_jsxs(_components.li,{children:[_jsx(_components.strong,{children:`Volumes:`}),` up to 20GB in total`]}),`
`,_jsxs(_components.li,{children:[_jsx(_components.strong,{children:`Sprites:`}),` up to 3 at a time`]}),`
`]}),`
`,_jsx(_components.p,{children:`Trial Machines stop automatically after running for 5 minutes. There’s no limit on the number of apps.`}),`
`,_jsx(_components.p,{children:`If you hit a trial limit, the error asks you to add a credit card, which lifts the limits.`}),`
`,_jsx(Tip,{children:_jsxs(_components.p,{children:[_jsx(_components.code,{children:`fly deploy`}),` creates 2 Machines per app by default, so 10 Machines covers 5 apps. Use `,_jsx(_components.code,{children:`fly deploy --ha=false`}),` to run 1 Machine per app.`]})}),`
`,_jsx(_components.p,{children:`These aren’t available during the trial:`}),`
`,_jsxs(_components.ul,{children:[`
`,_jsx(_components.li,{children:`Performance-optimized vCPUs`}),`
`,_jsx(_components.li,{children:`Dedicated IPv4 addresses`}),`
`,_jsx(_components.li,{children:`Extensions such as Tigris, Supabase and Upstash Redis`}),`
`]}),`
`,_jsx(_components.p,{children:`You can create a Managed Postgres cluster during the trial, but it uses up the $1 credit quickly.`}),`
`,_jsx(Info,{children:_jsx(_components.p,{children:`You can add a credit card from the dashboard at any time. This lifts the trial limits. Any credit you have left still applies, and your usage counts toward your bill once it’s used up.`})}),`
`,_jsx(Heading,{level:`2`,id:`checking-your-balance`,children:`Checking your balance`}),`
`,_jsxs(_components.p,{children:[`You can see how much credit you have left on the `,_jsx(_components.strong,{children:`Billing`}),` page in the Fly.io dashboard. While your trial is active, the dashboard also shows a banner with your remaining balance.`]}),`
